import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CYjxsSA2.js";const u=JSON.parse('{"title":"系统配置","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/settings.md","filePath":"advanced/settings.md"}'),o={name:"advanced/settings.md"};function l(n,t,s,i,h,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="系统配置" tabindex="-1">系统配置 <a class="header-anchor" href="#系统配置" aria-label="Permalink to &quot;系统配置&quot;">​</a></h1><p>系统配置集中管理平台的凭据、模型与集成项，顶部 <strong>8 个页签</strong>：</p><table tabindex="0"><thead><tr><th>页签</th><th>管什么</th></tr></thead><tbody><tr><td><strong>空间测绘</strong></td><td>FOFA / Quake / Hunter / Shodan 的平台凭据</td></tr><tr><td><strong>大模型配置</strong></td><td>Provider、模型列表、默认模型</td></tr><tr><td><strong>消息通知</strong></td><td>飞书 / 企业微信 Webhook 与通知组</td></tr><tr><td><strong>全局代理</strong></td><td>全局出口、代理池、按功能域路由</td></tr><tr><td><strong>智能体</strong></td><td>执行环境、工具与钩子、全局行为</td></tr><tr><td><strong>MCP</strong></td><td>外部 MCP 工具服务器</td></tr><tr><td><strong>Skills</strong></td><td>技能文件的启用、编辑与导入</td></tr><tr><td><strong>外观与语言</strong></td><td>主题与界面语言</td></tr></tbody></table><h2 id="大模型配置" tabindex="-1">大模型配置 <a class="header-anchor" href="#大模型配置" aria-label="Permalink to &quot;大模型配置&quot;">​</a></h2><ul><li>开箱即用预设：DeepSeek、GLM 智谱、通义千问</li><li>Anthropic Claude：原生接口格式</li><li>自定义：任意 OpenAI 兼容端点</li><li>多 Provider 并存，启用 / 禁用、切换默认模型、维护模型列表，保存后可做连通性验证</li></ul><p>详见<a href="/vaelor/guide/army.html#模型配置">军团智能体</a>。</p><h2 id="智能体" tabindex="-1">智能体 <a class="header-anchor" href="#智能体" aria-label="Permalink to &quot;智能体&quot;">​</a></h2><p>这一页管「军团到底怎么跑」，四个子页签：</p><h3 id="执行环境" tabindex="-1">执行环境 <a class="header-anchor" href="#执行环境" aria-label="Permalink to &quot;执行环境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>Kali Docker 工具箱</strong></td><td>隔离环境之一，见 <a href="/vaelor/advanced/docker.html">Kali 工具箱</a></td></tr><tr><td><strong>WSL 工具箱</strong></td><td>隔离环境之二（Windows）</td></tr><tr><td><strong>执行隔离档位</strong></td><td>不隔离 / 优先隔离（默认）/ 必须隔离</td></tr></tbody></table><p>档位选了「必须隔离」而两套工具箱都没启用时，设置页会直接提示命令会被拒绝。</p><h3 id="工具与钩子" tabindex="-1">工具与钩子 <a class="header-anchor" href="#工具与钩子" aria-label="Permalink to &quot;工具与钩子&quot;">​</a></h3><ul><li><strong>本地工具</strong> —— 军团能调用哪些本机工具</li><li><strong>钩子（Hooks）</strong> —— 把外部程序挂进动作链路：<strong>观察</strong>（只读旁路接收事件）或<strong>闸门</strong>（在工具执行前放行 / 拒绝）</li></ul><h3 id="全局行为" tabindex="-1">全局行为 <a class="header-anchor" href="#全局行为" aria-label="Permalink to &quot;全局行为&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>上下文窗口</td><td>会话上下文长度上限，接近上限自动压缩</td></tr><tr><td>按模型覆盖</td><td>为特定模型单独指定窗口与压缩参数</td></tr><tr><td>最大输出 Token</td><td>单轮回复长度上限</td></tr><tr><td>重试次数</td><td>模型 / 网络异常自动重试</td></tr><tr><td>模型请求超时</td><td>单次调用的整体上限，中转排队久时调大</td></tr><tr><td>流式空闲超时</td><td>多久没有新内容即判定挂死</td></tr><tr><td>折叠超长回复</td><td>长输出自动折叠</td></tr><tr><td>子进程网络抓包留痕</td><td>打开后子进程流量会留证</td></tr><tr><td>默认推理参数</td><td>最大推理步数、温度等</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">遇到「大模型连接失败」</p><p>先调大<strong>模型请求超时</strong>与<strong>流式空闲超时</strong>。慢推理模型与排队严重的中转站，固定超时容易误判。</p></div><h3 id="智能体角色" tabindex="-1">智能体角色 <a class="header-anchor" href="#智能体角色" aria-label="Permalink to &quot;智能体角色&quot;">​</a></h3><p>维护内置角色与自建角色：系统提示词、可用工具开关、Skills 挂载。</p><ul><li>不勾选任何工具，表示允许该角色使用全部内置工具</li></ul><h2 id="空间测绘凭据" tabindex="-1">空间测绘凭据 <a class="header-anchor" href="#空间测绘凭据" aria-label="Permalink to &quot;空间测绘凭据&quot;">​</a></h2><p>管理四个测绘平台的 API 凭据，可查看积分余额与会员等级；凭据缺失时该平台在空间测绘页不可用，其余平台不受影响。</p><h2 id="全局代理" tabindex="-1">全局代理 <a class="header-anchor" href="#全局代理" aria-label="Permalink to &quot;全局代理&quot;">​</a></h2><ul><li><strong>全局 HTTP 代理</strong> —— 所有出站请求统一走代理</li><li><strong>代理池</strong> —— 维护多个出口，军团遭遇 WAF 封禁时自动切换</li><li><strong>代理路由</strong> —— 按功能域单独指定出口（智能体 / 云上综合 / 目录扫描 / 大模型 / 消息通知 / 端口扫描 / 空间测绘 / 漏洞测绘 等）</li></ul><p>详见<a href="/vaelor/advanced/proxy.html">代理与网络出口</a>。</p><h2 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h2><p>按<strong>通知组</strong>管理多个飞书 / 企业微信 Webhook，项目可绑定不同组，并按严重等级设置推送阈值。详见<a href="/vaelor/advanced/notify.html">消息通知</a>。</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>接入外部 MCP 工具服务器（本地进程或网络端点），扩展军团能力边界。详见 <a href="/vaelor/advanced/mcp.html">MCP 外部工具服务器</a>。</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>技能文件的启用、编辑与导入；技能按需挂载到角色上。</p><h2 id="外观与语言" tabindex="-1">外观与语言 <a class="header-anchor" href="#外观与语言" aria-label="Permalink to &quot;外观与语言&quot;">​</a></h2><ul><li><strong>主题</strong> —— 浅色 / 深色，可跟随系统或手动指定；多套皮肤风格可切换</li><li><strong>界面语言</strong> —— 简体中文 / English / 한국어，未手动选择时跟随系统语言</li></ul>',32)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
